css:
:root {
  --paper:    #FFFFFF;
  --surface:  #FFFFFF;
  --sunk:     #F5F7FA;
  --band:     #EEF3FE;
  --ink:      #1F1F1F;
  --ink-2:    #3D4A5C;
  --muted:    #5B6876;
  --rule:     #E4E8EF;
  --rule-2:   #C6CFDC;
  --blue:     #0056D2;
  --blue-ink: #00419E;
  --blue-soft:#E3EDFD;
  --amber:    #B4690E;
  --amber-soft:rgba(180, 105, 14, 0.12);
  --teal:     #0F7B8A;
  --green:    #087443;

  --font-ui:   "Source Sans 3", "Source Sans Pro", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "JetBrains Mono", "DejaVu Sans Mono", Menlo, Consolas, monospace;

  --measure: 70ch;
  --gutter: clamp(1rem, 4vw, 2.5rem);
  --r: 8px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --paper:    #0F1319;
    --surface:  #171C24;
    --sunk:     #1C222C;
    --band:     #141C2B;
    --ink:      #EDF0F4;
    --ink-2:    #C3CBD6;
    --muted:    #8E9AA8;
    --rule:     #262E3A;
    --rule-2:   #364152;
    --blue:     #6BA4FF;
    --blue-ink: #9CC2FF;
    --blue-soft:rgba(107, 164, 255, 0.14);
    --amber:    #E0A544;
    --amber-soft:rgba(224, 165, 68, 0.16);
    --teal:     #4FC3D2;
    --green:    #4ECB8B;
  }
}
:root[data-theme="dark"] {
  --paper:#0F1319; --surface:#171C24; --sunk:#1C222C; --band:#141C2B;
  --ink:#EDF0F4; --ink-2:#C3CBD6; --muted:#8E9AA8; --rule:#262E3A; --rule-2:#364152;
  --blue:#6BA4FF; --blue-ink:#9CC2FF; --blue-soft:rgba(107,164,255,.14);
  --amber:#E0A544; --amber-soft:rgba(224,165,68,.16); --teal:#4FC3D2; --green:#4ECB8B;
}
:root[data-theme="light"] {
  --paper:#FFFFFF; --surface:#FFFFFF; --sunk:#F5F7FA; --band:#EEF3FE;
  --ink:#1F1F1F; --ink-2:#3D4A5C; --muted:#5B6876; --rule:#E4E8EF; --rule-2:#C6CFDC;
  --blue:#0056D2; --blue-ink:#00419E; --blue-soft:#E3EDFD;
  --amber:#B4690E; --amber-soft:rgba(180,105,14,.12); --teal:#0F7B8A; --green:#087443;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 17px;
  line-height: 1.6;
  -webkit-text-size-adjust: 100%;
}
.toolbar a:focus-visible, .toolbar button:focus-visible, summary:focus-visible {
  outline: 3px solid var(--blue); outline-offset: 2px;
}
.section { margin: 0 0 4rem; scroll-margin-top: 4.5rem; }
.q { margin: 0 0 1.5rem; scroll-margin-top: 4.5rem; border: 1px solid var(--rule); border-radius: var(--r); background: var(--surface); overflow: hidden; }
.prompt { padding: 0.2rem 1.2rem 1rem; margin: 0; max-width: var(--measure); color: var(--ink-2); }
.prompt p { margin: 0.4rem 0; }
.prompt ol, .prompt ul { margin: 0.4rem 0; padding-left: 1.3rem; }
.prompt li { margin: 0.15rem 0; }
details.sol { border-top: 1px solid var(--rule); background: var(--sunk); }
details.sol > summary {
  font-size: 0.85rem; font-weight: 700; color: var(--blue);
  padding: 0.7rem 1.2rem; cursor: pointer; list-style: none; user-select: none;
}
details.sol > summary::-webkit-details-marker { display: none; }
details.sol > summary::before { content: "▸ "; display: inline-block; }
details.sol[open] > summary::before { content: "▾ "; }
details.sol[open] > summary { border-bottom: 1px solid var(--rule); }
.sol-body { padding: 1.1rem 1.2rem 1.3rem; background: var(--surface); }
.sol-body > *:first-child { margin-top: 0; }
.sol-body > *:last-child { margin-bottom: 0; }
.sol-body p { max-width: var(--measure); margin: 0.75rem 0; }
.sol-body ul, .sol-body ol { max-width: var(--measure); padding-left: 1.25rem; }
.sol-body li { margin: 0.3rem 0; }
h3.part {
  font-size: 0.82rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--muted); margin: 1.6rem 0 0.6rem; padding-bottom: 0.25rem; border-bottom: 1px solid var(--rule);
}
.sol-body h3.part:first-child { margin-top: 0; }
.ans { font-weight: 700; color: var(--blue-ink); }
strong { font-weight: 700; }
code, .mono { font-family: var(--font-mono); font-size: 0.92em; font-variant-numeric: tabular-nums; }
.sol-body code { background: var(--sunk); padding: 0.08em 0.35em; border-radius: 4px; }
.work { overflow-x: auto; margin: 1rem 0; padding-bottom: 0.25rem; }
.row { display: flex; flex-wrap: wrap; align-items: center; gap: 1.4rem; }
.matrix {
  display: inline-grid; gap: 0.2rem 0.85rem; padding: 0.5rem 0.85rem; position: relative;
  font-family: var(--font-mono); font-size: 0.95rem; font-variant-numeric: tabular-nums;
  text-align: center; vertical-align: middle;
}
.matrix::before, .matrix::after { content: ""; position: absolute; top: 0; bottom: 0; width: 8px; border: 1.5px solid var(--ink-2); }
.matrix::before { left: 0; border-right: 0; }
.matrix::after  { right: 0; border-left: 0; }
.mlabel { font-family: var(--font-mono); font-weight: 700; font-size: 1rem; color: var(--ink-2); }
table.tbl { border-collapse: collapse; font-size: 0.9rem; font-variant-numeric: tabular-nums; min-width: min(100%, 20rem); }
table.tbl th, table.tbl td { border: 1px solid var(--rule-2); padding: 0.45rem 0.75rem; text-align: center; }
table.tbl th { background: var(--sunk); font-weight: 700; }
table.tbl td.lead, table.tbl th.lead { text-align: left; }
table.tbl tr.hi td { background: var(--blue-soft); }
table.tbl caption { caption-side: top; font-size: 0.82rem; color: var(--muted); text-align: left; padding-bottom: 0.4rem; }
table.kmap td { position: relative; width: 3.4rem; height: 2.6rem; font-size: 0.95rem; font-family: var(--font-mono); }
table.kmap td .mi { position: absolute; top: 2px; left: 4px; font-size: 0.6rem; color: var(--muted); }
.ring { position: absolute; border-radius: 5px; pointer-events: none; }
.ring.r1 { inset: 3px;  border: 2px solid var(--blue); }
.ring.r2 { inset: 7px;  border: 2px dashed var(--amber); }
.ring.r3 { inset: 11px; border: 2px dotted var(--teal); }
.ring.jl { border-left-color: transparent; border-top-left-radius: 0; border-bottom-left-radius: 0; }
.ring.jr { border-right-color: transparent; border-top-right-radius: 0; border-bottom-right-radius: 0; }
.ring.jt { border-top-color: transparent; border-top-left-radius: 0; border-top-right-radius: 0; }
.ring.jb { border-bottom-color: transparent; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.legend { display: flex; flex-wrap: wrap; gap: 0.4rem 1.2rem; font-size: 0.84rem; color: var(--muted); margin: 0.6rem 0 0; padding: 0; list-style: none; }
.legend li { display: flex; align-items: center; gap: 0.4rem; }
.swatch { width: 1.1rem; height: 0; border-top-width: 2px; border-top-style: solid; display: inline-block; }
.swatch.s1 { border-top-color: var(--blue); }
.swatch.s2 { border-top-color: var(--amber); border-top-style: dashed; }
.swatch.s3 { border-top-color: var(--teal); border-top-style: dotted; }
svg.dg { max-width: 100%; height: auto; font-family: var(--font-mono); }
svg.dg .node { fill: var(--surface); stroke: var(--ink-2); stroke-width: 1.5; }
svg.dg .node.acc { stroke: var(--blue); }
svg.dg .accring { fill: none; stroke: var(--blue); stroke-width: 1.5; }
svg.dg .edge { stroke: var(--ink-2); stroke-width: 1.4; fill: none; }
svg.dg .edge.hot { stroke: var(--blue); stroke-width: 2; }
svg.dg text { fill: var(--ink); font-size: 12px; }
svg.dg text.lbl { fill: var(--muted); font-size: 11px; }
svg.dg text.hot { fill: var(--blue); font-weight: 700; }
#arrow path { fill: var(--ink-2); }
#arrowhot path { fill: var(--blue); }
.note { border: 1px solid var(--rule-2); border-left: 4px solid var(--blue); border-radius: var(--r); background: var(--sunk); padding: 0.85rem 1rem; margin: 1rem 0; max-width: var(--measure); font-size: 0.95rem; }
.note .tag { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--blue); display: block; margin-bottom: 0.3rem; }
.note.warn { border-left-color: var(--amber); }
.note.warn .tag { color: var(--amber); }
.checks { list-style: none; padding: 0; margin: 1rem 0; max-width: var(--measure); }
.checks li { padding-left: 1.6rem; position: relative; margin: 0.35rem 0; }
.checks li::before { content: "✓"; position: absolute; left: 0; color: var(--green); font-weight: 700; }
footer.end { border-top: 2px solid var(--rule); padding-top: 1.5rem; font-size: 0.92rem; color: var(--muted); max-width: var(--measure); }
footer.end a { color: var(--blue); }
@media (max-width: 640px) {
  body { font-size: 16px; }
  .toolbar { gap: 0.25rem; }
  .toolbar a { padding: 0.35rem 0.55rem; font-size: 0.78rem; }
  .q-head { padding: 0.85rem 0.9rem 0.2rem; }
  .prompt { padding: 0.2rem 0.9rem 0.9rem; }
  .sol-body { padding: 0.9rem; }
  details.sol > summary { padding: 0.65rem 0.9rem; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }
html { scroll-padding-top: 5rem; }
img, svg, video, table { max-width: 100%; }
.sol-body, .prompt { overflow-wrap: break-word; }
body { font-size: clamp(15.5px, 0.55vw + 14.6px, 18px); }
footer.end { padding-bottom: 4.5rem; }
@media (max-width: 760px) {

  .toolbar {
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    gap: 0.3rem;
    padding: 0.5rem 0;
    margin-bottom: 1.75rem;

    margin-left: calc(var(--gutter) * -1);
    margin-right: calc(var(--gutter) * -1);
    padding-left: var(--gutter);
    padding-right: var(--gutter);
  }
  .toolbar::-webkit-scrollbar { display: none; }
  .toolbar a, .toolbar button { flex: none; white-space: nowrap; }
  .toolbar .spacer { display: none; }

  .masthead { padding: 2.25rem var(--gutter) 1.75rem; }
  .section { margin-bottom: 2.75rem; }
  .section-head { gap: 0.65rem; }
  .section-head .letter { width: 2rem; height: 2rem; font-size: 0.9rem; }
  .section-head h2 { font-size: 1.1rem; }
  .section-head .tally { flex-basis: 100%; }


  table.tbl { font-size: 0.84rem; }
  table.tbl th, table.tbl td { padding: 0.35rem 0.5rem; }
  .work { margin-left: calc(var(--gutter) * -0.5); margin-right: calc(var(--gutter) * -0.5); padding: 0 calc(var(--gutter) * 0.5) 0.25rem; }
  table.kmap td { width: 2.9rem; height: 2.3rem; }
}
@media (pointer: coarse) {
  .toolbar a, .toolbar button { min-height: 2.75rem; display: inline-flex; align-items: center; }
  details.sol > summary { padding-top: 0.9rem; padding-bottom: 0.9rem; }
  .q-head { padding-top: 1.1rem; }
}
@media (max-width: 380px) {
  :root { --gutter: 0.85rem; }
  .q-head { gap: 0.4rem; }
  .q-title { flex-basis: 100%; }
}
@media (min-width: 761px) and (max-width: 1100px) {
  .wrap { max-width: 100%; }
}
@media (min-width: 1400px) {
  .wrap { max-width: 1280px; }
  .masthead h1 { font-size: 3.3rem; }
}
.mk { color: var(--muted); font-size: 0.85em; font-variant-numeric: tabular-nums; white-space: nowrap; }
pre.code { font-family: var(--font-mono); font-size: 0.85rem; line-height: 1.55; background: var(--sunk); border: 1px solid var(--rule); border-radius: var(--r); padding: 0.85rem 1rem; margin: 1rem 0; max-width: var(--measure); overflow-x: auto; white-space: pre; }
pre.code code { background: none; padding: 0; border-radius: 0; font-size: 1em; }
